async (page) => { const context = page.context(); let collector = null; for (const candidate of context.pages()) { const flag = await candidate.evaluate(() => window.__isCollector === true).catch(() => false); if (flag) { collector = candidate; break; } } if (!collector) return { error: 'collector tab not found' }; const worker = context.pages().find((candidate) => candidate !== collector) || await context.newPage(); await worker.setViewportSize({ width: 1000, height: 1000 }); const jobs = await collector.evaluate(() => window.__jobs || []); await collector.evaluate(() => { window.__dumps = window.__dumps || []; }); const results = []; for (const job of jobs) { const result = { name: job.name, pages: 0, found: 0 }; try { let url = `https://t.me/s/${job.channel}?q=${encodeURIComponent(job.query)}`; for (let pageNumber = 1; pageNumber <= (job.maxPages || 12) && url; pageNumber += 1) { const response = await worker.goto(url, { waitUntil: 'load', timeout: 60000 }); await worker.waitForTimeout(1000); const dump = await worker.evaluate(async (extra) => { const more = [...document.querySelectorAll('a.tme_messages_more')].find((element) => element.getAttribute('data-before')); extra.tgSearch = { channelTitle: (document.querySelector('.tgme_channel_info_header_title') || {}).textContent || '', counters: (document.querySelector('.tgme_channel_info_counters') || {}).innerText || '', messages: [...document.querySelectorAll('.tgme_widget_message')].map((message) => window.__tg.parseMessage(message)), empty: (document.querySelector('.tme_no_messages_found') || {}).textContent || '', moreHref: more ? more.href : '', }; return window.__ac.dump(extra); }, { name: job.name + (pageNumber > 1 ? `_p${pageNumber}` : ''), status: response ? response.status() : null, requested: url, channel: job.channel, query: job.query, page: pageNumber }); await collector.evaluate((item) => { window.__dumps.push(item); }, dump); result.pages += 1; result.found += dump.extra.tgSearch.messages.length; if (dump.extra.tgSearch.empty.trim()) result.empty = dump.extra.tgSearch.empty.trim(); url = dump.extra.tgSearch.moreHref; } } catch (error) { result.error = String(error).slice(0, 200); } results.push(result); } return results; }
